package("expo-audio")
    set_kind("library", {headeronly = true})
    set_homepage("https://github.com/expo/expo/tree/main/packages/expo-audio")
    set_description("expo-audio 57.0.5, the Expo SDK audio player, recorder and stream, from its npm tarball: the iOS module sources the host builds from, patched to run on iOS 6 with each API the release lacks checked at run time (lock screen controls need iOS 7.1, AVAudioEngine streaming needs iOS 8, audio input selection needs iOS 7, and the iOS 10 player and now-playing calls have iOS 6 fallbacks)")
    set_license("MIT")
    set_policy("package.strict_compatibility", true)

    add_urls("https://registry.npmjs.org/expo-audio/-/expo-audio-$(version).tgz")
    add_versions("57.0.5", "5b26f87d644dfe05c7259d66078de98de7c9658c1e8a2041d2fe1fd51cf2f9b8")
    add_patches("57.0.5", path.join(os.scriptdir(), "patches", "mediacontroller-ios6.patch"), "46d938f98b7f718ebf49d177e7df2b572592ad7877dfb4e5203d223b9f4d9a84")
    add_patches("57.0.5", path.join(os.scriptdir(), "patches", "audiostream-ios6.patch"), "17270db2ad48ec3235619b0c970324b11c5a4e8e64fc5700fc00ae00df6084c9")
    add_patches("57.0.5", path.join(os.scriptdir(), "patches", "audioutils-ios6.patch"), "99c378994323453e5f8e3ed23baf1a8115eb313d5da076911ba9d1889f2e1c71")
    add_patches("57.0.5", path.join(os.scriptdir(), "patches", "audiorecords-ios6.patch"), "99b68903fb1f6afe3c0ae954edcf8a3f961e30a80d6e9a277d51437474848db6")
    add_patches("57.0.5", path.join(os.scriptdir(), "patches", "audioplayer-ios6.patch"), "5c129a5c50ebad96ed16c57a77e89f0725488ff24cd3a12c147cb98cf8afae48")
    add_patches("57.0.5", path.join(os.scriptdir(), "patches", "audiomodule-ios6.patch"), "b436ed50e8e7c289d42d424fb4c62737a4b10cc0821e56eb33442b0de2b4a305")

    on_install(function (package)
        os.cp("*", package:installdir() .. "/")
    end)

    on_test(function (package)
        local json = import("core.base.json")
        local manifest = json.decode(io.readfile(path.join(package:installdir(), "package.json")))
        assert(manifest.name == "expo-audio" and manifest.version == "57.0.5", "the package is " .. manifest.name .. " " .. manifest.version)
        assert(os.isfile(path.join(package:installdir(), "ios", "AudioModule.swift")), "expo-audio has no iOS module")
        assert(os.isfile(path.join(package:installdir(), "expo-module.config.json")), "expo-audio has no expo-module.config.json")
        assert(os.isfile(path.join(package:installdir(), "ios", "AVPlayerCompat.swift")), "the iOS 6 AVPlayer fallbacks are missing")
        assert(io.readfile(path.join(package:installdir(), "ios", "MediaController.swift")):find("@available(iOS 7.1, *)", 1, true), "MediaController is not guarded for iOS 7.1+")
        assert(io.readfile(path.join(package:installdir(), "ios", "AudioStream.swift")):find("@available(iOS 8.0, *)", 1, true), "the AVAudioEngine session is not guarded for iOS 8+")
        assert(io.readfile(path.join(package:installdir(), "ios", "AudioUtils.swift")):find("#available(iOS 7.0, *)", 1, true), "RecordingUtils is not guarded for iOS 7+")
        assert(os.isfile(path.join(package:installdir(), "ios", "AudioKeyPathObserver.swift")), "the iOS 6 key-value observer is missing")
        assert(not io.readfile(path.join(package:installdir(), "ios", "AudioPlayer.swift")):find("publisher(for:", 1, true), "AudioPlayer still uses Combine's key-value publisher, which iOS 6 lacks")
    end)
